command:
const MODULE_ID = "substances-and-paraphernalia";
const FLAG_SOURCE = "sourceSubstanceId";
if (!game.user.isGM) { ui.notifications.warn("GM only."); return; }
const actor = canvas.tokens.controlled[0]?.actor ?? game.user.character;
if (!actor) { ui.notifications.warn(game.i18n.localize("FISHUT.RemoveAddiction.NoActor")); return; }
const rows = [];
for (const effect of actor.effects) {
  const aeRole = effect.flags?.[MODULE_ID]?.aeRole ?? null;
  const legacy = aeRole == null && /addict/i.test(effect.name ?? "");
  if (aeRole !== "addiction" && !legacy) continue;
  if (legacy) console.warn(`[${MODULE_ID}] Remove Addiction: matched legacy AE "${effect.name}" by name substring (no aeRole flag).`);
  rows.push({ effect, sourceId: effect.flags?.[MODULE_ID]?.[FLAG_SOURCE] ?? null });
}
if (rows.length === 0) { ui.notifications.info(game.i18n.format("FISHUT.RemoveAddiction.NoCandidates", { actor: actor.name })); return; }
const body = `${game.i18n.format("FISHUT.RemoveAddiction.PreviewIntro", { actor: actor.name })}<ul style="list-style:none;padding-left:0;">${rows.map((r, i) => `<li><label><input type="checkbox" name="row-${i}" checked> ${game.i18n.format("FISHUT.RemoveAddiction.RowDetail", { name: r.effect.name, sourceId: r.sourceId ?? "(none)" })}</label></li>`).join("")}</ul>`;
const result = await foundry.applications.api.DialogV2.wait({
  window: { title: game.i18n.localize("FISHUT.RemoveAddiction.Title") },
  content: body,
  buttons: [
    { action: "confirm", label: game.i18n.localize("FISHUT.RemoveAddiction.Confirm"), default: true,
      callback: (event, button) => { const fd = new FormData(button.form); return rows.map((_, i) => fd.has(`row-${i}`)); } },
    { action: "cancel", label: game.i18n.localize("FISHUT.RemoveAddiction.Cancel"), default: false,
      callback: () => null }
  ],
  rejectClose: false, modal: true,
});
if (!Array.isArray(result)) return;
const chosen = rows.filter((_, i) => result[i]);
if (chosen.length === 0) return;
const log = chosen.map((r) => r.effect.toObject());
await actor.deleteEmbeddedDocuments("ActiveEffect", chosen.map((r) => r.effect.id), { fishutIntentional: true });
await ChatMessage.create({
  user: game.user.id,
  whisper: ChatMessage.getWhisperRecipients("GM").map((u) => u.id),
  content: `<details><summary>${game.i18n.localize("FISHUT.RemoveAddiction.LogTitle")}</summary><pre>${foundry.utils.escapeHTML(JSON.stringify(log, null, 2))}</pre></details>`,
});
ui.notifications.info(game.i18n.format("FISHUT.RemoveAddiction.Removed", { actor: actor.name, count: chosen.length }));
